@Composable
fun BaseNurTheme(content: @Composable () -> Unit) {

    val context = LocalContext.current
    val settingsPreference by lazy { AppSettingsPreference.getInstance(context) }

    NurTheme(
        colors = if (settingsPreference.isThemeLight()) nurDefaultLightColors() else nurDefaultDarkColors(),
        darkTheme = !settingsPreference.isThemeLight(),
        content = content
    )
}

